{
  "item_id": "PRISMA_2020_3",
  "elements": [
    {
      "element_id": "prisma_2020_3_e1",
      "status": "PARTIAL",
      "chunk_id": "text_2",
      "quote": "Background Despite advances made in curbing the global malaria burden since the 2000s, progress has stalled, in part due to a plateauing of the financing available to implement needed interventions.",
      "reason": "Provides context on external drivers (stalled progress/financing) but only partially describes the current state of knowledge and important uncertainties relevant to modeling for malaria optimization."
    },
    {
      "element_id": "prisma_2020_3_e2",
      "status": "PRESENT",
      "chunk_id": "text_2",
      "quote": "Models for malaria control optimization are used to disentangle the most efficient interventions or packages of interventions for inherently constrained budgets. This systematic review aimed to identify and characterise models for malaria control optimization for resource allocation in limited resource settings and assess their strengths and limitations.",
      "reason": "Explains the need for the review by stating the problem context and explicitly the review’s purpose/need (identify/characterise models and assess strengths/limitations)."
    },
    {
      "element_id": "prisma_2020_3_e3",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No evidence is provided describing similar systematic reviews, or explaining why a new review is needed when previous reviews exist (including updates/replications and citing prior reviews)."
    },
    {
      "element_id": "prisma_2020_3_e4",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "The review is about identifying/characterising optimization models for malaria control (a systematic review of models), and the retrieved evidence does not indicate an intervention-effect review where a mechanism of action of an intervention is required to be described."
    },
    {
      "element_id": "prisma_2020_3_e5",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "The retrieved evidence does not report a logic model to show hypothesised relationships between intervention components and outcomes for complex interventions/delivery contexts; moreover, this is a systematic review of optimization models rather than an intervention delivery logic-model specification."
    }
  ],
  "confidence": 62
}

{
  "item_id": "PRISMA_2020_4",
  "elements": [
    {
      "element_id": "prisma_2020_4_e1",
      "status": "PRESENT",
      "chunk_id": "text_6",
      "quote": "The research question for this review was ' Are there English-language publications in peer-reviewed scientific journals describing how models have been used to allocate resources for malaria interventions in limited resource settings?' The main aim of this review was to identify and characterize models for malaria control optimization for resource allocation in malaria control and elimination settings and to identify their strengths and limitations.",
      "reason": "The review provides an explicit research question and a stated main aim (objective) for the systematic review."
    },
    {
      "element_id": "prisma_2020_4_e2",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No planned intervention comparisons using PICO (or an appropriate variant) are stated in the retrieved evidence."
    }
  ],
  "confidence": 63
}

{
